import type { ErrorEnvelope, Paginated } from '@flowup/contracts';

/**
 * FE-01 D8 — typed fixtures for development and tests ONLY.
 *
 * `packages/contracts` currently defines the error and pagination envelopes
 * and nothing else: business DTOs arrive with the backend tasks that own their
 * routes (BE-04 onward), and `FE-xx` later consumes the types generated by
 * BE-14. Until then the shapes below mirror the examples in
 * `API_SPECIFICATION.md` §4–§5 and are confined to this directory
 * (AGENT_ADAPTER.md §6.2). They are never imported by production code, and no
 * production field is derived from them.
 *
 * Domain honesty (apps/web/AGENTS.md §5):
 *  - an event may have zero deliveries;
 *  - a failed ATTEMPT is not a failed DELIVERY;
 *  - an `UNKNOWN` attempt result exists and is not a confirmed failure;
 *  - `202` means accepted or scheduled, never delivered.
 *
 * No fixture contains a credential-shaped value (INV-08).
 */

export interface ApplicationFixture {
  id: string;
  name: string;
  status: 'ACTIVE' | 'DISABLED';
  created_at: string;
}

export interface DeliveryFixture {
  id: string;
  event_id: string;
  endpoint_id: string;
  status: 'PENDING' | 'IN_PROGRESS' | 'SUCCEEDED' | 'FAILED' | 'RETRY_WAIT' | 'CANCELLED';
  generation: number;
  attempt_count: number;
  next_attempt_at: string | null;
  last_error_code: string | null;
}

export interface EventFixture {
  id: string;
  status: 'accepted';
  application_id: string;
  type: string;
  delivery_count: number;
  no_matching_reason: 'no_matching_subscriptions' | null;
  accepted_at: string;
}

export const MOCK_ORGANIZATION_NAME = 'Example Organization (mock)';

export const applications: ApplicationFixture[] = [
  { id: 'app_001', name: 'Customer Alpha', status: 'ACTIVE', created_at: '2026-10-01T08:00:00Z' },
  { id: 'app_002', name: 'Customer Beta', status: 'DISABLED', created_at: '2026-10-02T09:30:00Z' },
  { id: 'app_003', name: 'Customer Gamma', status: 'ACTIVE', created_at: '2026-10-03T10:15:00Z' },
];

